ceName": "Margareta Karthäuserin", "verb": "INFLUENCES", "targetSlug": "female-monasticism-medieval", "targetName": "Female Monasticism (Medieval)", "context": "Margareta Karthäuserin's high-quality scribal work exemplifies and illuminates the intellectual and artistic contributions of women within medieval monastic communities."}, {"sourceSlug": "johannes-gutenberg", "sourceName": "Johannes Gutenberg", "verb": "OCCURS_DURING", "targetSlug": "margareta-karthuserin", "targetName": "Margareta Karthäuserin", "context": "Johannes Gutenberg's development of the printing press in the 1450s coincided with Margareta Karthäuserin's active scribal career, highlighting a period of transition in book production technologies."}], "places": [{"name": "Nuremberg, Holy Roman Empire", "role": "Center of activity"}, {"name": "Saint Catherine's Convent, Nuremberg", "role": "Monastic home and workshop"}, {"name": "Bavaria, Holy Roman Empire", "role": "Regional context"}], "texts": [{"title": "Wikipedia: Margareta Karthäuserin", "type": "Reference article", "slug": "margareta-karthäuserin"}], "externalLinks": ["https://www.wikidata.org/wiki/Q16851748", "https://en.wikipedia.org/wiki/Margareta_Karth%C3%A4userin"], "tags": ["Religious Figures", "comparative-religion", "doctrine-development", "cultural-diffusion"], "thumbnailUrl": "", "quote": "", "legacySummary": "Margareta Karthäuserin left a notable mark on Medieval history, documented across 0 Wikipedia editions worldwide. Key lasting impacts include: Shaped religious practice and spiritual communities; Contributed to synthesis of classical and religious thought informing Renaissance and Reformati.", "historicalSignificance": {"significanceScore": 7, "significanceNarrative": "Margareta Karthäuserin's skilled scribal work provides crucial evidence of the intellectual and artistic contributions of women in late medieval monasticism, challenging traditional narratives of male dominance in book production and illuminating regional cultural practices. Her surviving manuscripts are vital primary sources for understanding 15th-century German religious and artistic life.", "significanceCategory": "regional"}, "_editLog": [{"timestamp": "2026-08-06T07:03:19Z", "editorId": "gemini-2.5-flash·cloud·GH#31079290366", "field": "summary", "oldValue": "Margareta Karthäuserin was a mid-15th century nun at the Dominican convent of Saint Catherine in Nuremberg and an exceptionally skilled scribe.", "newValue": "Margareta Karthäuserin (c. 1420–1480) stands out as a preeminent Dominican nun and master scribe at Saint Catherine's Convent in Nuremberg during the mid-15th century. Her meticulous work in producing liturgical and devotional manuscripts demonstrates the high intellectual and artistic standards upheld by female monastic communities in late medieval Germany, providing crucial counter-evidence to historical narratives that often emphasize male dominance in the craft of book production.

From approximately the mid-1440s until her death around 1480, Margareta meticulously copied, illuminated, and occasionally bound numerous codices. Her extensive output included essential choir books, antiphonaries, and prayer books, frequently featuring intricate Gothic textura script and vibrant initial decorations. A notable example is a large-format antiphonary completed in 1461, showcasing her exceptional calligraphic precision and artistic flair, which served the demanding liturgical needs of her community and potentially other patrons in the region.

